import{_ as d,o as a,c as e,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"GEICO（盖可保险，政府雇员保险公司）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/GEICO.md","filePath":"03_companies/GEICO.md"}'),o={name:"03_companies/GEICO.md"};function l(i,t,h,u,n,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="geico-盖可保险-政府雇员保险公司" tabindex="-1">GEICO（盖可保险，政府雇员保险公司） <a class="header-anchor" href="#geico-盖可保险-政府雇员保险公司" aria-label="Permalink to &quot;GEICO（盖可保险，政府雇员保险公司）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>GEICO (Government Employees Insurance Company)</td></tr><tr><td>行业</td><td>汽车保险</td></tr><tr><td>成立年份</td><td>1936年</td></tr><tr><td>创始人</td><td><a href="/search?q=利奥·古德温">利奥·古德温</a> 与 <a href="/search?q=莉莉安·古德温">莉莉安·古德温</a></td></tr><tr><td>总部</td><td>马里兰州 Chevy Chase</td></tr><tr><td>伯克希尔持股</td><td>100%全资控股（1996年完成收购）</td></tr><tr><td>伯克希尔总投资成本</td><td>约23.47亿美元（分两步收购）</td></tr><tr><td>初始投资成本</td><td>约4,700万美元（1976-1980年买入约1/3股份）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>GEICO是美国第二大汽车保险公司，也是美国最大的汽车保险直销公司，通过电话和互联网直接面向消费者销售保险产品，省去中间代理商环节，实现行业领先的低成本运营。主要业务覆盖全美50个州的个人汽车保险，同时也提供其他财产险产品。</p><h2 id="与伯克希尔的关系-完整时间线" tabindex="-1">与伯克希尔的关系（完整时间线） <a class="header-anchor" href="#与伯克希尔的关系-完整时间线" aria-label="Permalink to &quot;与伯克希尔的关系（完整时间线）&quot;">​</a></h2><h3 id="_1-1951年-巴菲特初次接触" tabindex="-1">1. 1951年：巴菲特初次接触 <a class="header-anchor" href="#_1-1951年-巴菲特初次接触" aria-label="Permalink to &quot;1. 1951年：巴菲特初次接触&quot;">​</a></h3><ul><li>1951年1月，20岁的巴菲特还是哥伦比亚大学学生，慕名前往GEICO总部拜访</li><li>当时恰逢周六，公司大楼关闭，但看门人为他开门，遇到了时任副总裁（后成为CEO）的<a href="/search?q=洛里默·戴维森">洛里默·戴维森</a></li><li>戴维森花了4个小时向巴菲特讲解GEICO的商业模式和竞争优势，这次会面彻底改变了巴菲特，让他深刻理解了保险行业的魅力</li><li>巴菲特将自己净资产的<strong>65%</strong>（约6,700美元）买入GEICO股票，年底持仓占比超过<strong>70%</strong>，并在当年为《商业与金融纪事报》撰写文章，称GEICO为&quot;我最喜欢的证券&quot;</li><li>巴菲特卖出大部分持仓获利，但保留了对公司的长期关注</li></ul><h3 id="_2-1970年代-危机降临" tabindex="-1">2. 1970年代：危机降临 <a class="header-anchor" href="#_2-1970年代-危机降临" aria-label="Permalink to &quot;2. 1970年代：危机降临&quot;">​</a></h3><ul><li>1970年代初，GEICO管理层在理赔成本估算上犯了严重错误，导致定价严重偏低</li><li>公司因激进扩张濒临破产，股价从60美元暴跌至1976年的不到5美元</li></ul><h3 id="_3-1976年-伯克希尔大举买入" tabindex="-1">3. 1976年：伯克希尔大举买入 <a class="header-anchor" href="#_3-1976年-伯克希尔大举买入" aria-label="Permalink to &quot;3. 1976年：伯克希尔大举买入&quot;">​</a></h3><ul><li><a href="/04_people/杰克·伯恩">杰克·伯恩</a>出任CEO，采取果断措施拯救公司</li><li>巴菲特确认GEICO的核心低成本竞争优势依然完好，认定这是绝佳投资机会</li><li>伯克希尔从1976年下半年开始大量买入，到1980年底累计投入<strong>4,570万美元</strong>，获得约**33.3%**的股份</li></ul><h3 id="_4-1976-1995年-股权逐步集中" tabindex="-1">4. 1976-1995年：股权逐步集中 <a class="header-anchor" href="#_4-1976-1995年-股权逐步集中" aria-label="Permalink to &quot;4. 1976-1995年：股权逐步集中&quot;">​</a></h3><ul><li>GEICO复苏后持续回购自家股票，伯克希尔持股比例被动提升至约<strong>50%</strong></li><li>这一阶段，巴菲特称GEICO为&quot;我们最重要的非控股持仓，代表伯克希尔最大的未分配盈利来源&quot;</li></ul><h3 id="_5-1995-1996年-全资收购" tabindex="-1">5. 1995-1996年：全资收购 <a class="header-anchor" href="#_5-1995-1996年-全资收购" aria-label="Permalink to &quot;5. 1995-1996年：全资收购&quot;">​</a></h3><ul><li>1995年，伯克希尔同意以<strong>23亿美元</strong>收购剩余50%股份</li><li>1996年1月完成收购，GEICO成为伯克希尔100%全资子公司</li><li>伯克希尔两步收购总成本约<strong>23.47亿美元</strong></li></ul><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-不可复制的直销低成本模式" tabindex="-1">1. 不可复制的直销低成本模式 <a class="header-anchor" href="#_1-不可复制的直销低成本模式" aria-label="Permalink to &quot;1. 不可复制的直销低成本模式&quot;">​</a></h3><ul><li>无代理商佣金体系，相比传统代理模式节省**15-20%**的运营成本</li><li>这种成本优势可以转化为给客户更低的价格，吸引更多客户，形成良性循环</li><li>&quot;当一家公司销售具有商品类经济特征的产品时，成为低成本生产商至关重要&quot;（巴菲特，2000年）</li></ul><h3 id="_2-持续提升的运营效率" tabindex="-1">2. 持续提升的运营效率 <a class="header-anchor" href="#_2-持续提升的运营效率" aria-label="Permalink to &quot;2. 持续提升的运营效率&quot;">​</a></h3><ul><li>1983年综合成本率<strong>96</strong>，远优于行业平均111</li><li>2003-2006年，保单数量从570万份增长到810万份（+42%），但全职员工数量反而下降<strong>3.5%</strong>，生产力提升47%</li><li>2003-2005年，两年内生产率提升<strong>32%</strong>，保单增长26%同时员工减少4%</li></ul><h3 id="_3-强大的品牌认知" tabindex="-1">3. 强大的品牌认知 <a class="header-anchor" href="#_3-强大的品牌认知" aria-label="Permalink to &quot;3. 强大的品牌认知&quot;">​</a></h3><ul><li>&quot;15分钟省15%或更多的汽车保险&quot;广告语深入人心</li><li>吉祥物壁虎（Gecko）家喻户晓，广告转化率持续提升</li><li>2006年广告支出6.31亿美元，远高于1995年伯克希尔收购时的3,100万美元</li></ul><h3 id="_4-可扩展的护城河" tabindex="-1">4. 可扩展的护城河 <a class="header-anchor" href="#_4-可扩展的护城河" aria-label="Permalink to &quot;4. 可扩展的护城河&quot;">​</a></h3><ul><li>GEICO的低成本创造了一条<strong>持久的护城河</strong>，竞争对手无法跨越</li><li>年复一年持续蚕食市场份额，从1995年的2.5%增长到2016年的12%</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;1951年1月我第一次接触GEICO时，我被该公司相对于行业巨头所承受费用的巨大成本优势所震撼。我清楚地看到GEICO会成功，因为它值得成功。&quot; —— 2014年股东信</p></blockquote><blockquote><p>&quot;GEICO拥有极端且不断提升的运营效率，其成本优势广泛且可持续。&quot; —— 1983年股东信</p></blockquote><blockquote><p>&quot;GEICO是我们最重要的非控股持仓，代表伯克希尔最大的未分配盈利来源。&quot; —— 1981年股东信</p></blockquote><blockquote><p>&quot;卢·辛普森是财产意外险行业最好的投资经理。&quot; —— 1984年股东信</p></blockquote><blockquote><p>&quot;尽管那里我们在业务投资方面的准备没有那么充分。这里有一段历史：曾有一段时间，查理是我投资的潜在接替者，最近卢·辛普森填补了这个位置。卢是一流投资者，管理GEICO股票组合的长期记录出色。&quot; —— 2006年股东信</p></blockquote><blockquote><p>&quot;GEICO的成本优势是使该公司年复一年吞噬市场份额的因素。公司的低成本创造了一条护城河——一条持久的护城河，竞争对手无法跨越。&quot; —— 2014年股东信</p></blockquote><blockquote><p>&quot;我爱这个小家伙（指壁虎吉祥物）。&quot; —— 2014年股东信</p></blockquote><blockquote><p>&quot;这个简单的公式55年前第一次让我发现GEICO时就给我留下了深刻印象。确实，在21岁时，我写了一篇关于这家公司的文章——当时它的市值只有700万美元。如你所见，我把GEICO称为&#39;我最喜欢的证券&#39;。至今我仍然这样称呼它。&quot; —— 2005年股东信</p></blockquote><blockquote><p>&quot;GEICO不是普通的保险公司：由于公司的低成本，其保单持有人始终盈利且异常忠诚。&quot; —— 2010年股东信</p></blockquote><blockquote><p>&quot;GEICO——是一个持续给予的礼物。&quot; —— 2010年股东信</p></blockquote><blockquote><p>&quot;1951年1月，20岁的我首次拜访GEICO时就对其充满热情，如今在托尼的带领下，我更加兴奋。&quot; —— 2009年股东信</p></blockquote><blockquote><p>&quot;如果我没有遇到<a href="/search?q=洛里默·戴维森">洛里默·戴维森</a>，我可能永远不会理解整个保险领域，而保险这些年来在伯克希尔哈撒韦的成功中发挥了如此关键的作用。&quot; —— 1997年股东信</p></blockquote><blockquote><p>&quot;虽然它们当然远小于GEICO，但我们其他主要保险业务去年的业绩总体上同样惊人。&quot; —— 1997年股东信</p></blockquote><blockquote><p>&quot;坦白说，如果你有新生的儿子或孙子，一定要给他取名叫托尼。&quot; —— 2005年股东信</p></blockquote><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>链接</th><th>贡献</th></tr></thead><tbody><tr><td><a href="/search?q=利奥·古德温">利奥·古德温</a></td><td>创始人</td><td><a href="/search?q=利奥·古德温">利奥·古德温</a></td><td>1936年创立GEICO，开创直销保险新模式</td></tr><tr><td><a href="/search?q=莉莉安·古德温">莉莉安·古德温</a></td><td>联合创始人</td><td><a href="/search?q=莉莉安·古德温">莉莉安·古德温</a></td><td>与丈夫共同创立GEICO</td></tr><tr><td><a href="/search?q=洛里默·戴维森">洛里默·戴维森</a></td><td>前CEO</td><td><a href="/search?q=洛里默·戴维森">洛里默·戴维森</a></td><td>1951年向巴菲特启蒙GEICO商业模式，后带领公司增长</td></tr><tr><td><a href="/04_people/杰克·伯恩">杰克·伯恩</a></td><td>CEO (1976-1985)</td><td><a href="/04_people/杰克·伯恩">杰克·伯恩</a></td><td>从破产边缘拯救公司，重建承保纪律</td></tr><tr><td><a href="/04_people/比尔·斯奈德">比尔·斯奈德</a></td><td>董事长 (1985-1992)</td><td><a href="/04_people/比尔·斯奈德">比尔·斯奈德</a></td><td>继续压低成本，巩固特许权</td></tr><tr><td><a href="/04_people/卢·辛普森">卢·辛普森</a></td><td>投资负责人</td><td><a href="/04_people/卢·辛普森">卢·辛普森</a></td><td>管理GEICO投资组合近30年，长期跑赢标普500</td></tr><tr><td><a href="/search?q=托尼·奈斯利">托尼·奈斯利</a></td><td>CEO (1992-2018)</td><td><a href="/search?q=托尼·奈斯利">托尼·奈斯利</a></td><td>18岁加入公司，带领GEICO从2.5%市场份额增长到12%</td></tr></tbody></table><h2 id="财务表现-关键节点" tabindex="-1">财务表现（关键节点） <a class="header-anchor" href="#财务表现-关键节点" aria-label="Permalink to &quot;财务表现（关键节点）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>保费收入</th><th>市场份额</th><th>有效保单</th><th>浮存金</th><th>综合成本率</th><th>备注</th></tr></thead><tbody><tr><td>1937</td><td>23.8万美元</td><td>-</td><td>-</td><td>-</td><td>-</td><td>首个完整运营年度</td></tr><tr><td>1951</td><td>800万美元</td><td>&lt;1%</td><td>-</td><td>-</td><td>-</td><td>巴菲特初次投资时市值仅700万美元</td></tr><tr><td>1981</td><td>约2.7亿美元</td><td>-</td><td>-</td><td>-</td><td>约98</td><td>远优于行业平均</td></tr><tr><td>1983</td><td>约3.5亿美元</td><td>-</td><td>-</td><td>-</td><td>96</td><td>行业最佳水平</td></tr><tr><td>1986</td><td>超5亿美元</td><td>-</td><td>-</td><td>-</td><td>96.9</td><td>三年保费翻倍</td></tr><tr><td>1995</td><td>28亿美元</td><td>2.5%</td><td>-</td><td>25亿美元</td><td>-</td><td>伯克希尔收购控制权时</td></tr><tr><td>1996</td><td>29亿美元</td><td>-</td><td>-</td><td>27亿美元</td><td>-</td><td>完成全资收购</td></tr><tr><td>2002</td><td>69亿美元</td><td>-</td><td>-</td><td>-</td><td>-</td><td>六年增长138%</td></tr><tr><td>2005</td><td>-</td><td>6.1%</td><td>-</td><td>-</td><td>-</td><td>十年增长2.4倍</td></tr><tr><td>2008</td><td>-</td><td>7.7%</td><td>-</td><td>-</td><td>-</td><td>跃升为美国第三大汽车保险公司</td></tr><tr><td>2009</td><td>-</td><td>8.1%</td><td>净增700万保单</td><td>96亿美元</td><td>-</td><td>13年中13年承保盈利</td></tr><tr><td>2010</td><td>143亿美元</td><td>-</td><td>-</td><td>-</td><td>-</td><td>14年保费增长407%</td></tr><tr><td>2012</td><td>167亿美元</td><td>9.7%</td><td>-</td><td>-</td><td>-</td><td>持续增长</td></tr><tr><td>2014</td><td>-</td><td>10.8%</td><td>-</td><td>-</td><td>-</td><td>收购后市场份额翻两番</td></tr><tr><td>2015</td><td>-</td><td>11.4%</td><td>-</td><td>-</td><td>-</td><td>持续扩张</td></tr><tr><td>2016</td><td>-</td><td>12%</td><td>-</td><td>-</td><td>-</td><td>员工从8,575人增长到36,085人</td></tr><tr><td>2018</td><td>-</td><td>-</td><td>-</td><td>221亿美元</td><td>-</td><td>自收购以来承保利润累计155亿美元（税前）</td></tr><tr><td>2020</td><td>350亿美元</td><td>~13%</td><td>-</td><td>-</td><td>-</td><td>最新规模</td></tr></tbody></table><h2 id="投资回报总结" tabindex="-1">投资回报总结 <a class="header-anchor" href="#投资回报总结" aria-label="Permalink to &quot;投资回报总结&quot;">​</a></h2><ul><li><strong>1976-1980年</strong>：伯克希尔投入4,700万美元获得1/3股权</li><li><strong>1996年</strong>：花费23亿美元收购剩余50%股权，企业整体估值46亿美元</li><li><strong>2010年</strong>：仅经济商誉估值已达约140亿美元</li><li><strong>2013年</strong>：巴菲特估计真实经济商誉接近<strong>200亿美元</strong></li><li><strong>截至2018年</strong>：浮存金从25亿美元增长到221亿美元，累计税前承保利润155亿美元</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1977, 1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2020</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/喜诗糖果">喜诗糖果</a> - 同为伯克希尔经典长期投资</li><li><a href="/03_companies/华盛顿邮报">华盛顿邮报</a> - 同为经典非控股投资案例</li><li><a href="/03_companies/国家赔偿公司">国家赔偿公司</a> - <a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>保险板块核心</li><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> - 母公司</li><li><a href="/04_people/阿吉特·贾恩">阿吉特·贾恩</a> - 伯克希尔再保险负责人</li></ul><hr><p><em>最后更新：2026-04-16</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1977年/翻译">/01_letters/1977年/翻译</a></li><li><a href="/01_letters/1978年/翻译">/01_letters/1978年/翻译</a></li><li><a href="/01_letters/翻译">/01_letters//翻译</a></li><li><a href="/01_letters/翻译">/01_letters//翻译</a></li></ul>',55)])])}const b=d(o,[["render",l]]);export{c as __pageData,b as default};
